function Field({ label }) {
  const id = useId();
  return (
    <p>
      <label htmlFor={id}>{label}</label>
      <input id={id} />
    </p>
  );
}

function App() {
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <Field label="First name" />
      <Field label="Last name" />
    </div>
  );
}

function LabeledInput({ label, help, type = 'text' }) {
  const id = useId();
  return (
    <p>
      <label htmlFor={id} style={{ display: 'block', marginBottom: 4 }}>{label}</label>
      <input id={id} type={type} aria-describedby={help ? `${id}-help` : undefined} />
      {help && <span id={`${id}-help`} style={{ color: '#666' }}>{help}</span>}
    </p>
  );
}

function App() {
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <LabeledInput label="Email" type="email" help="We never share it." />
      <LabeledInput label="Display name" help="Shown on your profile." />
    </div>
  );
}
